#include <assert.h>
#include <string>

template <std::size_t MaxSize, class T> struct tiny_size_allocator {
  using value_type = T;
  using size_type = unsigned;

  template <class U> struct rebind {
    using other = tiny_size_allocator<MaxSize, U>;
  };

  tiny_size_allocator() = default;

  template <class U> tiny_size_allocator(tiny_size_allocator<MaxSize, U>) {}

  T *allocate(std::size_t n) {
    assert(n <= MaxSize);
    return std::allocator<T>().allocate(n);
  }

  void deallocate(T *ptr, std::size_t n) {
    std::allocator<T>().deallocate(ptr, n);
  }

  size_type max_size() const { return MaxSize; }

  friend bool operator==(tiny_size_allocator, tiny_size_allocator) {
    return true;
  }
};

int main(void) {
  using string_type = std::basic_string<char, std::char_traits<char>,
                                        tiny_size_allocator<17, char>>;
  string_type s;
  s.resize(s.max_size(), 'a');
  assert(s.size() == s.max_size());
  s.replace(0, 0, "", 0);  // specified to throw length_error
}
